import { createRequire, isBuiltin } from 'node:module';
import path from 'node:path';
import { pathToFileURL, fileURLToPath } from 'node:url';

const REQUIRER_BASENAME = '__resolve_anchor__.js';

/**
 * Create a CommonJS require() anchored at `basedir` so that relative and bare
 * specifiers are resolved exactly as Node would from a module in that directory.
 */
function requireFrom(basedir) {
  return createRequire(path.join(basedir, REQUIRER_BASENAME));
}

/**
 * Resolve a module specifier using Node's own resolution algorithm.
 *
 * @param {string} specifier  Bare, relative, absolute or `node:` specifier.
 * @param {object} [options]
 * @param {string} [options.basedir=process.cwd()] Directory resolution starts from.
 * @returns {string} Absolute path to the resolved file.
 * @throws {Error} If the specifier cannot be resolved.
 */
export function resolve(specifier, { basedir = process.cwd() } = {}) {
  const result = resolveDetailed(specifier, { basedir });
  if (!result.path) {
    throw new Error(`Cannot resolve builtin module '${specifier}' to a file path`);
  }
  return result.path;
}

/**
 * Resolve a specifier and return structured metadata about the result.
 *
 * @param {string} specifier
 * @param {object} [options]
 * @param {string} [options.basedir=process.cwd()]
 * @returns {{ specifier: string, path: string|null, url: string, builtin: boolean }}
 */
export function resolveDetailed(specifier, { basedir = process.cwd() } = {}) {
  if (isBuiltin(specifier)) {
    const url = specifier.startsWith('node:') ? specifier : `node:${specifier}`;
    return { specifier, path: null, url, builtin: true };
  }

  const resolved = requireFrom(path.resolve(basedir)).resolve(specifier);
  return {
    specifier,
    path: resolved,
    url: pathToFileURL(resolved).href,
    builtin: false,
  };
}

/**
 * Resolve a specifier relative to a module identified by a file URL.
 *
 * @param {string} specifier
 * @param {string|URL} parentUrl
 * @returns {{ specifier: string, path: string|null, url: string, builtin: boolean }}
 */
export function resolveFromUrl(specifier, parentUrl) {
  const basedir = path.dirname(fileURLToPath(parentUrl));
  return resolveDetailed(specifier, { basedir });
}

/**
 * Return the directories Node would search for a bare specifier, nearest first.
 *
 * @param {string} specifier
 * @param {object} [options]
 * @param {string} [options.basedir=process.cwd()]
 * @returns {string[]}
 */
export function resolveSearchPaths(specifier, { basedir = process.cwd() } = {}) {
  return createRequire(path.join(path.resolve(basedir), REQUIRER_BASENAME))
    .resolve
    .paths(specifier) ?? [];
}

export {
  resolve,
  resolveDetailed,
  resolveFromUrl,
  resolveSearchPaths,
} from './resolver.js';

import test from 'node:test';
import assert from 'node:assert/strict';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

import {
  resolve,
  resolveDetailed,
  resolveFromUrl,
  resolveSearchPaths,
} from '../src/index.js';

const here = path.dirname(fileURLToPath(import.meta.url));
const root = path.resolve(here, '..');

test('resolves core modules without touching the filesystem', () => {
  const fs = resolveDetailed('node:fs');
  assert.equal(fs.builtin, true);
  assert.equal(fs.url, 'node:fs');
  assert.equal(fs.path, null);

  const bare = resolveDetailed('path');
  assert.equal(bare.builtin, true);
  assert.equal(bare.url, 'node:path');
});

test('resolves relative specifiers from basedir', () => {
  const resolved = resolve('./fixtures/target.js', { basedir: here });
  assert.equal(resolved, path.join(here, 'fixtures', 'target.js'));
});

test('applies Node extension probing', () => {
  const resolved = resolve('./fixtures/target', { basedir: here });
  assert.equal(resolved, path.join(here, 'fixtures', 'target.js'));
});

test('resolves directory index files', () => {
  const resolved = resolve('./fixtures/dir', { basedir: here });
  assert.equal(resolved, path.join(here, 'fixtures', 'dir', 'index.js'));
});

test('resolves the package self-reference through "exports"', () => {
  const resolved = resolve('node-resolve-tool', { basedir: root });
  assert.equal(resolved, path.join(root, 'src', 'index.js'));
});

test('resolveFromUrl uses the parent module location', () => {
  const parent = new URL('./fixtures/entry.js', import.meta.url);
  const resolved = resolveFromUrl('./target.js', parent);
  assert.equal(resolved, path.join(here, 'fixtures', 'target.js'));
});

test('resolveSearchPaths returns node_modules candidates', () => {
  const paths = resolveSearchPaths('some-pkg', { basedir: path.join(here, 'fixtures', 'dir') });
  assert.ok(paths.some((p) => p.endsWith(path.join('fixtures', 'dir', 'node_modules'))));
  assert.ok(paths.some((p) => p.endsWith(path.join('test', 'node_modules'))));
});

test('throws a useful error for unresolvable specifiers', () => {
  assert.throws(
    () => resolve('./does-not-exist', { basedir: here }),
    /Cannot find module/,
  );
});

